class Solution {
public:
    int maxCandies(vector<int>& status, vector<int>& candies,
                   vector<vector<int>>& keys, vector<vector<int>>& containedBoxes,
                   vector<int>& initialBoxes) {
        int n = status.size(), total = 0;
        vector<bool> owned(n, false), opened(n, false);
        queue<int> q;
        for (int b : initialBoxes) {
            owned[b] = true;
            if (status[b]) q.push(b);
        }
        while (!q.empty()) {
            int b = q.front(); q.pop();
            if (opened[b] || !owned[b] || !status[b]) continue;
            opened[b] = true;
            total += candies[b];
            for (int k : keys[b]) {
                status[k] = 1;
                if (owned[k] && !opened[k]) q.push(k);
            }
            for (int x : containedBoxes[b]) {
                owned[x] = true;
                if (status[x] && !opened[x]) q.push(x);
            }
        }
        return total;
    }
};
